import{_ as t,o as d,a as o,a2 as a}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"Understanding the Core Class","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/understanding-core-class.md","filePath":"advanced/understanding-core-class.md","lastUpdated":1790143103000}'),r={name:"advanced/understanding-core-class.md"};function c(n,e,s,i,h,l){return d(),o("div",null,e[0]||(e[0]=[a(`<h1 id="understanding-the-core-class" tabindex="-1">Understanding the Core Class <a class="header-anchor" href="#understanding-the-core-class" aria-label="Permalink to &quot;Understanding the Core Class&quot;">​</a></h1><p><code>Webkul\\Core\\Core</code>, in <code>packages/Webkul/Core/src/Core.php</code>, holds the store-wide lookups most Bagisto code needs: the current channel, locale and currency, price conversion and formatting, the saved configuration, countries and states, and a few utilities. You reach it through the global <code>core()</code> helper, which returns the instance behind the <code>Webkul\\Core\\Facades\\Core</code> facade, so every call in one request or one queued job talks to the same object, and that object <a href="#things-to-watch">remembers what it looks up</a>.</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$channelCode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> core</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getCurrentChannelCode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$total </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> core</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">formatPrice</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($amount, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EUR&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$maxAttempts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> core</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getConfigData</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sales.order_settings.order_creation.max_retry_attempts&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h2 id="how-the-current-context-is-resolved" tabindex="-1">How the Current Context Is Resolved <a class="header-anchor" href="#how-the-current-context-is-resolved" aria-label="Permalink to &quot;How the Current Context Is Resolved&quot;">​</a></h2><p>Each of these values is resolved once, then the remembered model is returned:</p><table tabindex="0"><thead><tr><th>Value</th><th>Resolved from</th><th>Fallback</th></tr></thead><tbody><tr><td>Current channel</td><td>The channel whose <code>hostname</code> matches the request host, with or without <code>http://</code> or <code>https://</code></td><td>The first channel</td></tr><tr><td>Default channel</td><td>The channel whose code is <code>config(&#39;app.channel&#39;)</code></td><td>The first channel</td></tr><tr><td>Current locale</td><td>The locale whose code is <code>app()-&gt;getLocale()</code></td><td>The locale for <code>config(&#39;app.fallback_locale&#39;)</code></td></tr><tr><td>Base currency</td><td>The currency whose code is <code>config(&#39;app.currency&#39;)</code></td><td>The first currency</td></tr><tr><td>Current currency</td><td>The currency last passed to <code>setCurrentCurrency()</code></td><td>The current channel&#39;s base currency</td></tr></tbody></table><p>The &quot;requested&quot; methods read the admin&#39;s channel and locale switchers instead, the <code>channel</code> and <code>locale</code> query parameters; they&#39;re in the tables below.</p><h2 id="method-reference" tabindex="-1">Method Reference <a class="header-anchor" href="#method-reference" aria-label="Permalink to &quot;Method Reference&quot;">​</a></h2><p>Signatures are as declared in <code>Core.php</code> and its <code>Webkul\\Core\\Concerns\\CurrencyFormatter</code> trait.</p><h3 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Returns</th></tr></thead><tbody><tr><td><code>getAllChannels()</code></td><td>Every channel</td></tr><tr><td><code>getCurrentChannel(?string $hostname = null)</code></td><td>The current channel. <code>$hostname</code> replaces the request host, but only on the first call</td></tr><tr><td><code>setCurrentChannel(Channel $channel): void</code></td><td>Makes <code>$channel</code> the current channel</td></tr><tr><td><code>getCurrentChannelCode(): ?string</code></td><td>The current channel&#39;s code</td></tr><tr><td><code>getDefaultChannel(): ?Channel</code></td><td>The default channel</td></tr><tr><td><code>setDefaultChannel(Channel $channel): void</code></td><td>Makes <code>$channel</code> the default channel</td></tr><tr><td><code>getDefaultChannelCode(): ?string</code></td><td>The default channel&#39;s code</td></tr><tr><td><code>getDefaultLocaleCodeFromDefaultChannel(): string</code></td><td>The default locale code of the default channel</td></tr><tr><td><code>getRequestedChannel()</code></td><td>The channel named by the <code>channel</code> query parameter, <code>null</code> when no channel has that code, or the current channel when the parameter is absent</td></tr><tr><td><code>getRequestedChannelCode($fallback = true)</code></td><td>The <code>channel</code> request input; with <code>$fallback</code>, the current and then the default channel code when it is empty</td></tr><tr><td><code>getChannelName($channel): string</code></td><td>The channel&#39;s name, falling back to its translation in the app locale and then the fallback locale</td></tr></tbody></table><h3 id="locales" tabindex="-1">Locales <a class="header-anchor" href="#locales" aria-label="Permalink to &quot;Locales&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Returns</th></tr></thead><tbody><tr><td><code>getAllLocales()</code></td><td>Every locale, sorted by name</td></tr><tr><td><code>getCurrentLocale()</code></td><td>The current locale</td></tr><tr><td><code>getRequestedLocale()</code></td><td>The locale named by the <code>locale</code> query parameter, <code>null</code> when no locale has that code, or the current locale when the parameter is absent</td></tr><tr><td><code>getRequestedLocaleCode($localeKey = &#39;locale&#39;, $fallback = true)</code></td><td>The <code>$localeKey</code> request input; with <code>$fallback</code>, <code>app()-&gt;getLocale()</code> when it is empty</td></tr><tr><td><code>getRequestedLocaleCodes($localeKey = &#39;locale&#39;): array</code></td><td>Every locale code when the input is <code>all</code>, otherwise a one-item array of the requested code</td></tr><tr><td><code>getRequestedLocaleCodeInRequestedChannel()</code></td><td>The requested locale code when the requested channel has that locale, otherwise the channel&#39;s default locale code</td></tr></tbody></table><h3 id="currencies-and-prices" tabindex="-1">Currencies and Prices <a class="header-anchor" href="#currencies-and-prices" aria-label="Permalink to &quot;Currencies and Prices&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Returns</th></tr></thead><tbody><tr><td><code>getAllCurrencies()</code></td><td>Every currency</td></tr><tr><td><code>getBaseCurrency()</code></td><td>The base currency</td></tr><tr><td><code>getBaseCurrencyCode()</code></td><td>The base currency code</td></tr><tr><td><code>getChannelBaseCurrency()</code></td><td>The current channel&#39;s base currency</td></tr><tr><td><code>getChannelBaseCurrencyCode()</code></td><td>The current channel&#39;s base currency code</td></tr><tr><td><code>setCurrentCurrency($currencyCode)</code></td><td>Sets the current currency; an unknown code selects the channel&#39;s base currency</td></tr><tr><td><code>getCurrentCurrency()</code></td><td>The current currency</td></tr><tr><td><code>getCurrentCurrencyCode()</code></td><td>The current currency code</td></tr><tr><td><code>getExchangeRate($targetCurrencyId)</code></td><td>The exchange rate row for a currency <strong>id</strong>, or <code>null</code></td></tr><tr><td><code>convertPrice($amount, $targetCurrencyCode = null)</code></td><td><code>$amount</code> multiplied by the target currency&#39;s rate (the current currency when no code is given); unchanged when there is no rate</td></tr><tr><td><code>convertToBasePrice($amount, $targetCurrencyCode = null)</code></td><td><code>$amount</code> divided by the target currency&#39;s rate; unchanged when there is no rate</td></tr><tr><td><code>currency($amount = 0)</code></td><td><code>$amount</code> converted to the current currency and formatted</td></tr><tr><td><code>formatPrice(?float $price, ?string $currencyCode = null): string</code></td><td><code>$price</code> formatted in the given or current currency, <strong>without</strong> converting it</td></tr><tr><td><code>formatBasePrice(?float $price): string</code></td><td><code>$price</code> formatted in the base currency</td></tr><tr><td><code>formatCurrency(?float $price, Currency $currency): string</code></td><td><code>$price</code> formatted for the app locale: with the currency&#39;s position, decimals and separators when its <code>currency_position</code> is set, otherwise in the locale&#39;s own format with the currency&#39;s symbol</td></tr><tr><td><code>useDefaultCurrencyFormatter(?float $price, Currency $currency): string</code></td><td>The locale&#39;s currency format, using the currency&#39;s own symbol when it differs from the locale&#39;s</td></tr><tr><td><code>useCustomCurrencyFormatter(?float $price, Currency $currency): string</code></td><td>The number with the currency&#39;s decimals and separators, and its symbol, or its code when it has none, placed by <code>currency_position</code></td></tr><tr><td><code>currencySymbol($currency): string</code></td><td>The locale&#39;s symbol for a currency code or <code>Currency</code> model</td></tr></tbody></table><h3 id="dates" tabindex="-1">Dates <a class="header-anchor" href="#dates" aria-label="Permalink to &quot;Dates&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Returns</th></tr></thead><tbody><tr><td><code>isChannelDateInInterval($dateFrom = null, $dateTo = null)</code></td><td>Whether today, in the current channel&#39;s timezone, is between the two dates inclusive; an empty date leaves that side open</td></tr><tr><td><code>channelTimeStamp($channel)</code></td><td>The current Unix timestamp; the channel&#39;s timezone doesn&#39;t change it</td></tr><tr><td><code>is_empty_date($date)</code></td><td>Whether a SQL date such as <code>0000-00-00 00:00:00</code> is empty</td></tr><tr><td><code>formatDate($date = null, $format = &#39;d-m-Y H:i:s&#39;)</code></td><td>The date (now when <code>null</code>) in the current channel&#39;s timezone, formatted with Carbon&#39;s <code>translatedFormat()</code></td></tr><tr><td><code>xWeekRange($date, $day)</code></td><td>As <code>Y-m-d</code>, the Sunday on or before <code>$date</code> when <code>$day</code> is <code>0</code>, otherwise the Saturday on or after it</td></tr></tbody></table><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Returns</th></tr></thead><tbody><tr><td><code>getConfigData(string $field, ?string $currentChannelCode = null, ?string $currentLocaleCode = null): mixed</code></td><td>The saved configuration value. The codes default to <code>getRequestedChannelCode()</code> and <code>getRequestedLocaleCode()</code>: the request&#39;s <code>channel</code> and <code>locale</code> input, then the current channel and the app locale. Delegates to <code>system_config()-&gt;getConfigData()</code></td></tr><tr><td><code>getConfigField($fieldName)</code></td><td>The field definition from the <code>core</code> configuration tree</td></tr></tbody></table><p>A value that has never been saved falls back to <code>config()</code> at the same key without its first segment (<code>sales.payment_methods.&lt;code&gt;.&lt;field&gt;</code> reads <code>config(&#39;payment_methods.&lt;code&gt;.&lt;field&gt;&#39;)</code>), then to the field&#39;s <code>default</code> in <code>system.php</code>; see <a href="./../package-development/system-configuration.html#configuration-value-resolution">System Configuration</a>.</p><h3 id="countries-and-addresses" tabindex="-1">Countries and Addresses <a class="header-anchor" href="#countries-and-addresses" aria-label="Permalink to &quot;Countries and Addresses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Returns</th></tr></thead><tbody><tr><td><code>countries()</code></td><td>Every row of the <code>countries</code> table</td></tr><tr><td><code>country_name($code)</code></td><td>The country name for an ISO 3166-1 alpha-2 code, or an empty string</td></tr><tr><td><code>states($countryCode)</code></td><td>The states of a country</td></tr><tr><td><code>groupedStatesByCountries()</code></td><td>Every state, grouped in an array keyed by country code</td></tr><tr><td><code>findStateByCountryCode($countryCode = null, $stateCode = null)</code></td><td>The matching state, or <code>false</code></td></tr><tr><td><code>isCountryRequired()</code>, <code>isStateRequired()</code>, <code>isPostCodeRequired()</code></td><td>Whether the address field is required, from <code>customer.address.requirements.*</code></td></tr></tbody></table><h3 id="customers-taxes-and-email" tabindex="-1">Customers, Taxes and Email <a class="header-anchor" href="#customers-taxes-and-email" aria-label="Permalink to &quot;Customers, Taxes and Email&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Returns</th></tr></thead><tbody><tr><td><code>getGuestCustomerGroup()</code></td><td>The customer group with the code <code>guest</code></td></tr><tr><td><code>getTaxCategoryById($id)</code></td><td>The tax category, or <code>null</code> for an empty id</td></tr><tr><td><code>Core::taxRateAsIdentifier(float $taxRate): string</code></td><td>Static. The rate with dots replaced by underscores, for use in element ids</td></tr><tr><td><code>getSenderEmailDetails()</code></td><td><code>[&#39;name&#39; =&gt; …, &#39;email&#39; =&gt; …]</code> from <code>emails.configure.email_settings.sender_*</code>, falling back to <code>config(&#39;mail.from&#39;)</code></td></tr><tr><td><code>getAdminEmailDetails()</code></td><td>The same shape from <code>admin_name</code> and <code>admin_email</code>, falling back to <code>config(&#39;mail.admin&#39;)</code> and then <code>config(&#39;mail.from&#39;)</code></td></tr><tr><td><code>getContactEmailDetails()</code></td><td>The same shape from <code>contact_name</code> and <code>contact_email</code>, falling back to <code>config(&#39;mail.contact&#39;)</code> and then <code>config(&#39;mail.from&#39;)</code></td></tr></tbody></table><h3 id="utilities" tabindex="-1">Utilities <a class="header-anchor" href="#utilities" aria-label="Permalink to &quot;Utilities&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Returns</th></tr></thead><tbody><tr><td><code>version()</code></td><td>The value of <code>Core::BAGISTO_VERSION</code></td></tr><tr><td><code>getMaxUploadSize()</code></td><td>PHP&#39;s <code>upload_max_filesize</code> setting</td></tr><tr><td><code>convertEmptyStringsToNull($array)</code></td><td>The array with empty strings and the string <code>&#39;null&#39;</code> replaced by <code>null</code></td></tr><tr><td><code>getSingletonInstance($className)</code></td><td>One instance of <code>$className</code> per <code>Core</code> instance, resolved from the container</td></tr><tr><td><code>getSpeculationRules()</code></td><td>The browser speculation rules (<code>prerender</code> and <code>prefetch</code>) built from <code>general.content.speculation_rules.*</code></td></tr></tbody></table><h2 id="other-global-helpers" tabindex="-1">Other Global Helpers <a class="header-anchor" href="#other-global-helpers" aria-label="Permalink to &quot;Other Global Helpers&quot;">​</a></h2><p>Each of these is defined in its package&#39;s <code>src/Http/helpers.php</code> and available everywhere without an import.</p><table tabindex="0"><thead><tr><th>Helper</th><th>Package</th><th>Returns</th></tr></thead><tbody><tr><td><code>core()</code></td><td>Core</td><td><code>Webkul\\Core\\Core</code></td></tr><tr><td><code>menu()</code></td><td>Core</td><td><code>Webkul\\Core\\Menu</code>; <code>menu()-&gt;getItems(Menu::ADMIN)</code></td></tr><tr><td><code>acl()</code></td><td>Core</td><td><code>Webkul\\Core\\Acl</code></td></tr><tr><td><code>system_config()</code></td><td>Core</td><td><code>Webkul\\Core\\SystemConfig</code></td></tr><tr><td><code>db_grammar()</code></td><td>Core</td><td><code>Webkul\\Core\\Contracts\\DatabaseGrammar</code> for the current database. See <a href="./database-compatibility.html">Database Compatibility</a></td></tr><tr><td><code>clean_path(string $path)</code></td><td>Core</td><td>The path with empty segments removed</td></tr><tr><td><code>clean_content(string $content)</code></td><td>Core</td><td>HTML purified and stripped of Blade directives</td></tr><tr><td><code>array_permutation($input)</code></td><td>Core</td><td>Every combination of an array of arrays</td></tr><tr><td><code>themes()</code></td><td>Theme</td><td><code>Webkul\\Theme\\Themes</code>; <code>themes()-&gt;current()</code>, <code>themes()-&gt;set($themeName)</code></td></tr><tr><td><code>bagisto_asset(string $path, ?string $namespace = null)</code></td><td>Theme</td><td>The Vite URL of a theme asset</td></tr><tr><td><code>bagisto_theme_storage()</code></td><td>Theme</td><td><code>Webkul\\Theme\\ThemeStorage</code> for section media URLs</td></tr><tr><td><code>view_render_event(string $eventName, mixed $params = null)</code></td><td>Theme</td><td>Rendered listener output. See <a href="./view-render-events.html">View Render Events</a></td></tr><tr><td><code>product_image()</code></td><td>Product</td><td><code>Webkul\\Product\\ProductImage</code></td></tr><tr><td><code>product_video()</code></td><td>Product</td><td><code>Webkul\\Product\\ProductVideo</code></td></tr><tr><td><code>product_toolbar()</code></td><td>Product</td><td><code>Webkul\\Product\\Helpers\\Toolbar</code> (sort orders and page limits)</td></tr><tr><td><code>image_manager()</code></td><td>ImageCache</td><td><code>Illuminate\\Image\\ImageManager</code></td></tr><tr><td><code>image_urls(string $path, ?string $key = null)</code></td><td>ImageCache</td><td>The <code>*_image_url</code> set for a stored path. See <a href="./../theme-development/image-cache-templates.html">Image Cache</a></td></tr><tr><td><code>datagrid(string $datagridClass)</code></td><td>DataGrid</td><td>A resolved DataGrid instance</td></tr><tr><td><code>cart()</code></td><td>Checkout</td><td><code>Webkul\\Checkout\\Cart</code></td></tr><tr><td><code>payment()</code></td><td>Payment</td><td><code>Webkul\\Payment\\Payment</code></td></tr><tr><td><code>shipping()</code></td><td>Shipping</td><td><code>Webkul\\Shipping\\Shipping</code></td></tr><tr><td><code>magic_ai()</code></td><td>MagicAI</td><td><code>Webkul\\MagicAI\\MagicAI</code></td></tr><tr><td><code>bouncer()</code></td><td>User</td><td><code>Webkul\\User\\Bouncer</code>; <code>hasPermission()</code>, and the static <code>allow()</code></td></tr><tr><td><code>two_factor_authentication()</code></td><td>User</td><td><code>Webkul\\User\\TwoFactorAuthentication</code></td></tr></tbody></table><p><code>db_grammar()</code>, <code>bagisto_theme_storage()</code> and <code>image_urls()</code> were added in Bagisto 2.5, and on Bagisto 2.4 <code>image_manager()</code> returns <code>Intervention\\Image\\ImageManager</code>. There is no <code>theme()</code>, <code>visitor()</code> or <code>money_format()</code> helper.</p><h2 id="things-to-watch" tabindex="-1">Things to Watch <a class="header-anchor" href="#things-to-watch" aria-label="Permalink to &quot;Things to Watch&quot;">​</a></h2><ul><li><strong><code>core()</code> remembers for one request or one job, then starts fresh.</strong> The current and default channel, the current and base currency, the current locale, the guest customer group, exchange rates and tax categories are looked up once and kept on the instance. <code>Webkul\\Core\\Core</code> has no container binding: the instance is the one the facade caches, and <code>php artisan queue:work</code> clears that cache before every job, as Laravel Octane does for every request. Code that works through several channels in one job must call <code>setCurrentChannel()</code>, and <code>setCurrentCurrency()</code>, which is remembered separately, for each one.</li><li><strong>A command or queued job has no browser request.</strong> Laravel builds the console request from <code>APP_URL</code>, so <code>getCurrentChannel()</code> returns the channel whose hostname matches <code>APP_URL</code>, or the first channel.</li><li><strong><code>formatPrice()</code> doesn&#39;t convert; <code>currency()</code> does.</strong> <code>currency()</code> converts from the base currency before formatting, so an amount already in the order&#39;s currency is converted twice.</li><li><strong><code>getConfigData()</code> isn&#39;t <code>config()</code>.</strong> It reads the configuration saved from the admin, per channel and locale, from the database.</li><li><strong><code>countries()</code> and <code>groupedStatesByCountries()</code> query the database on every call.</strong> Call them once per request and reuse the result.</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./../package-development/system-configuration.html">System Configuration</a>: declaring the fields <code>getConfigData()</code> reads.</li><li><a href="./understanding-indexers.html">Understanding Indexers</a>: the price, inventory and flat indexes the storefront reads.</li><li><a href="./database-compatibility.html">Database Compatibility</a>: the <code>db_grammar()</code> helper.</li><li><a href="./view-render-events.html">View Render Events</a>: the <code>view_render_event()</code> helper.</li></ul>`,34)]))}const m=t(r,[["render",c]]);export{g as __pageData,m as default};
